        internal const uint M8_FLOWER_PLANE_U_SHIFT = 0x00000002u;
        internal const uint M8_FLOWER_PLANE_V_SHIFT = 0x0000000cu;
        internal const uint M8_FLOWER_PLANE_OFFSET_SHIFT = 0x00000016u;
        internal const uint M8_FLOWER_PLANE_VALID = 0x80000000u;
        internal const uint M8_FLOWER_PLANE_FREE_SIDE = 0x40000000u;
        internal const uint M8_FLOWER_PLANE_STORAGE_MASK = 0xfffffffcu;
        internal const uint M8_FLOWER_OCCUPIED_FLAG = 0x00000001u;
        internal const uint M8_FLOWER_SEED_FLAG = 0x00000002u;
        internal const uint M8_FLOWER_OCCUPIED_ON = 0x00000200u;
        internal const uint M8_FLOWER_OCCUPIED_OFF = 0x00000080u;
        internal const uint M8_FLOWER_EVIDENCE_LIMIT = 0x00000a00u;
        internal const uint M8_FLOWER_SURFACE_EVIDENCE = 0x00000280u;
        internal const uint M8_FLOWER_THROUGH_EVIDENCE = 0x00000100u;
        internal const float M8_FLOWER_PLANE_RANGE = 0.0250000004f;

internal static uint2 M8FlowerPositiveQuotientBracket(float numerator,float denominator)
{
    if(!TryDivideEnclosed(numerator,denominator,out FloatInterval bracket))
        return uint2(0xffffffffu,0xffffffffu);
    return uint2(asuint(bracket.Lower),asuint(bracket.Upper));
}

internal static int M8FlowerCompareRoundMidpoint(uint lo,uint hi,float denominator,
    float value)
{
    double sum=(double)asfloat(lo)+asfloat(hi);
    double product=sum*denominator;
    double target=2.0*value;
    return product<target?-1:(product>target?1:0);
}


internal static uint M8FlowerNearestBracket(uint lo,uint hi,int midpointComparison)
{
    if(lo==hi)return lo;
    if(midpointComparison<0)return hi;
    if(midpointComparison>0)return lo;
    return (lo&1u)==0u?lo:hi;
}

internal static float M8FlowerRoundDivide(float numerator,float denominator)
{
    uint n=asuint(numerator),d=asuint(denominator);
    uint magnitude=n&0x7fffffffu;
    if(magnitude>=0x7f800000u || d==0u || d>=0x7f800000u)
        return asfloat(0x7fc00000u);
    if(magnitude==0u)return numerator;
    float positive=asfloat(magnitude);
    uint2 bracket=M8FlowerPositiveQuotientBracket(positive,denominator);
    if(bracket.x==0xffffffffu)return asfloat(0x7fc00000u);
    uint rounded=bracket.x;
    if(bracket.x!=bracket.y)
        rounded=M8FlowerNearestBracket(bracket.x,bracket.y,
            M8FlowerCompareRoundMidpoint(bracket.x,bracket.y,denominator,positive));
    return asfloat(rounded|(n&0x80000000u));
}

internal static float M8FlowerRoundSqrt(float value)
{
    uint bits=asuint(value);
    if((bits&0x7fffffffu)==0u)return value;
    if(bits>=0x7f800000u)return asfloat(0x7fc00000u);
    uint encodedExponent=bits>>23;
    uint mantissa=(bits&0x7fffffu)|(encodedExponent!=0u?0x800000u:0u);
    int exponent=encodedExponent!=0u?(int)encodedExponent-127:-126;
    int normalization=23-(31-lzcnt(mantissa));
    mantissa<<=normalization;exponent-=normalization;
    int parity=exponent&1;
    int shift=23+parity;
    // Normalize even subnormals into [1,4). Vulkan InverseSqrt is <=2 ULP;
    // multiplying by this normal input adds <=0.5 ULP. In the integer-root
    // scale the total error is <4.5, hence at most five floor corrections.
    // https://docs.vulkan.org/spec/latest/appendices/spirvenv.html#spirvenv-precision-operation
    float scaled=asfloat(((uint)(127+parity)<<23)|(mantissa&0x7fffffu));
    float hint=scaled*rsqrt(scaled);
    uint root=(uint)(hint*8388608.0f);
    // |D-root^2| < 2^28. Its low word interpreted as signed is the EXACT
    // remainder even though D and the square separately have up to48 bits.
    int remainder=asint((mantissa<<shift)-root*root);
    for(int correction=0;correction<5;++correction)
    {
        int down=remainder<0?1:0;
        int up=remainder>=(int)(2u*root+1u)?1:0;
        remainder+=down*(int)(2u*root-1u)-up*(int)(2u*root+1u);
        root=(uint)((int)root+up-down);
    }
    if(remainder<0 || remainder>=(int)(2u*root+1u))return asfloat(0x7fc00000u);
    // D=q^2+r. The midpoint square is q^2+q+1/4: integral D can
    // never tie, and nearest rounding increments q exactly when r>q.
    if((uint)remainder>root)++root;
    int rootExponent=(exponent-parity)/2;
    // All positive binary32 square roots are normal. Addition also handles
    // the carry when rounding a24bit significand across a power of two.
    return asfloat(((uint)(rootExponent+127)<<23)+root-0x800000u);
}


internal static bool M8FlowerHasPlane(uint flags)
{
    return (flags & M8_FLOWER_PLANE_VALID) != 0u;
}

internal static uint M8FlowerClearPlane(uint flags)
{
    return flags & ~M8_FLOWER_PLANE_STORAGE_MASK;
}

internal static int M8FlowerPlaneFreeSide(uint flags)
{
    return (flags & M8_FLOWER_PLANE_FREE_SIDE) != 0u ? -1 : 1;
}

internal static float2 M8FlowerOctSigns(float2 value)
{
    return float2(value.x < 0.0f ? -1.0f : 1.0f,
        value.y < 0.0f ? -1.0f : 1.0f);
}

internal static bool M8FlowerTryPackPlane(uint flags, float3 normal,
    float signedOffset, out uint packed)
{
    packed = flags;
    if (!all(isfinite(normal)) || !isfinite(signedOffset) ||
        abs(signedOffset) > M8_FLOWER_PLANE_RANGE) return false;
    float3 square = normal * normal;
    float squareXY = square.x + square.y;
    float lengthSquared = squareXY + square.z;
    if (!(lengthSquared > 0.0f) || !isfinite(lengthSquared)) return false;
    float normalLength = sqrt(lengthSquared);
    normal /= normalLength;
    float first = normal.x != 0.0f ? normal.x :
        normal.y != 0.0f ? normal.y : normal.z;
    bool reversed = first < 0.0f;
    if (reversed)
    {
        normal = -normal;
        signedOffset = -signedOffset;
    }
    float sumXY = abs(normal.x) + abs(normal.y);
    float sum = sumXY + abs(normal.z);
    normal /= sum;
    float2 oct = normal.xy;
    if (normal.z < 0.0f)
        oct = (1.0f - abs(oct.yx)) * M8FlowerOctSigns(oct);
    float2 halfOct = oct * 0.5f;
    float2 unitOct = halfOct + 0.5f;
    float2 code = round(unitOct * 1023.0f);
    float normalizedOffset = signedOffset / M8_FLOWER_PLANE_RANGE;
    int offsetCode = (int)round(normalizedOffset * 127.0f);
    if (any(code < 0.0f) || any(code > 1023.0f) ||
        offsetCode < -127 || offsetCode > 127) return false;
    packed = M8FlowerClearPlane(flags) |
        ((uint)code.x << (int)M8_FLOWER_PLANE_U_SHIFT) |
        ((uint)code.y << (int)M8_FLOWER_PLANE_V_SHIFT) |
        (((uint)offsetCode & 255u) << (int)M8_FLOWER_PLANE_OFFSET_SHIFT) |
        M8_FLOWER_PLANE_VALID |
        (reversed ? M8_FLOWER_PLANE_FREE_SIDE : 0u);
    return true;
}

internal static void M8FlowerUnpackPlane(uint flags, out float3 normal,
    out float signedOffset)
{
    uint u = (flags >> (int)M8_FLOWER_PLANE_U_SHIFT) & 1023u;
    uint v = (flags >> (int)M8_FLOWER_PLANE_V_SHIFT) & 1023u;
    // Exact numerators of the same octahedral code centre, with denominator
    // 1023. This common positive factor cancels during normalization; decoding
    // it first in binary32 would break exact equal-component symmetries.
    int x = 2 * (int)u - 1023;
    int y = 2 * (int)v - 1023;
    int z = 1023 - abs(x) - abs(y);
    if (z < 0)
    {
        int previousX = x;
        x = (x < 0 ? -1 : 1) * (1023 - abs(y));
        y = (y < 0 ? -1 : 1) * (1023 - abs(previousX));
    }
    // Every numerator is bounded by 1023; the integer squares and their sum
    // are exactly representable in binary32 before the shared RNE operations.
    normal = float3(x, y, z);
    float3 square = normal * normal;
    float squareXY = square.x + square.y;
    float lengthSquared = squareXY + square.z;
    float normalLength = M8FlowerRoundSqrt(lengthSquared);
    for(uint axis=0u;axis<3u;axis++)
        normal[(int)axis] = M8FlowerRoundDivide(normal[(int)axis],normalLength);
    uint raw = (flags >> (int)M8_FLOWER_PLANE_OFFSET_SHIFT) & 255u;
    int offsetCode = raw >= 128u ? (int)raw - 256 : (int)raw;
    float unitOffset = M8FlowerRoundDivide((float)offsetCode,127.0f);
    signedOffset = unitOffset * M8_FLOWER_PLANE_RANGE;
}

// The caller proves these predicates from fixed incidence / interval roots.
// It applies direct admission once per immutable observation, not per quantum.
internal static uint4 M8FlowerAdmitR1(uint4 state, uint measuredPlane,
    uint capturedColor, bool compatiblePrior, bool differentObservation,
    bool sameObservationClosure)
{
    if (!M8FlowerHasPlane(measuredPlane)) return state;
    bool occupied = (state.w & M8_FLOWER_OCCUPIED_FLAG) != 0u;
    bool seed = !occupied && M8FlowerHasPlane(state.w) &&
        (state.w & M8_FLOWER_SEED_FLAG) != 0u;
    if (occupied && !compatiblePrior) return state;
    bool promote = sameObservationClosure ||
        (seed && compatiblePrior && differentObservation);
    uint flags = measuredPlane & M8_FLOWER_PLANE_STORAGE_MASK;
    int evidence;
    if (occupied || promote)
    {
        int before = occupied || (seed && compatiblePrior) ?
            max(0, asint(state.x)) : 0;
        evidence = min((int)M8_FLOWER_EVIDENCE_LIMIT,
            max((int)M8_FLOWER_OCCUPIED_ON,
                before + (int)M8_FLOWER_SURFACE_EVIDENCE));
        flags |= M8_FLOWER_OCCUPIED_FLAG;
    }
    else
    {
        evidence = min((int)M8_FLOWER_OCCUPIED_ON - 1,
            (int)M8_FLOWER_SURFACE_EVIDENCE);
        flags |= M8_FLOWER_SEED_FLAG;
    }
    return uint4(asuint(evidence), capturedColor, 1u, flags);
}

// Only full-support THROUGH may call this. It neither creates negative M8
// authority nor relies on normal neighbours to keep a contradicted ghost.
internal static uint4 M8FlowerContradictR1(uint4 state)
{
    bool occupied = (state.w & M8_FLOWER_OCCUPIED_FLAG) != 0u;
    if (!occupied)
        return (state.w & M8_FLOWER_SEED_FLAG) != 0u ? uint4(0u,0u,0u,0u) : state;
    int evidence = asint(state.x) - (int)M8_FLOWER_THROUGH_EVIDENCE;
    if (evidence <= (int)M8_FLOWER_OCCUPIED_OFF) return uint4(0u,0u,0u,0u);
    state.x = asuint(evidence);
    return state;
}

